export function upgradeSubscription(userId, plan, addons = []) {
  if (!userId) {
    throw new Error('userId is required');
  }

  if (!PLAN_PRICES[plan]) {
    throw new Error(`Invalid plan: ${plan}. Must be one of: ${Object.keys(PLAN_PRICES).join(', ')}`);
  }

  const invalidAddons = addons.filter(addon => !ADDON_PRICES[addon]);
  if (invalidAddons.length > 0) {
    throw new Error(`Invalid addons: ${invalidAddons.join(', ')}`);
  }

  const price = calculatePrice(plan, addons);
  return {
    userId,
    plan,
    addons,
    price,
    upgradedAt: new Date().toISOString()
  };
}

